"""Local OpenAI-compatible GKA proxy for Customer Zero verification.

The proxy keeps the existing Morris Law Kernel service untouched on port 8080.
It carves older chat context locally, forwards the optimized prompt to the
configured live Gemini provider, and returns OpenAI-compatible JSON plus GKA
telemetry headers.
"""

from __future__ import annotations

import json
import math
import os
import subprocess
import sys
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from time import perf_counter
from uuid import uuid4

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))

from main import GKA_CORE, gemini_dispatch


def estimate_tokens(value: str) -> int:
    normalized = value.strip()
    return 0 if not normalized else math.ceil(len(normalized) / 4)


def content_text(content: object) -> str:
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        return "\n".join(
            part.get("text", "")
            for part in content
            if isinstance(part, dict) and isinstance(part.get("text"), str)
        )
    return json.dumps(content, separators=(",", ":"), ensure_ascii=False)


def normalize_message(message: object) -> dict[str, str]:
    if not isinstance(message, dict):
        raise ValueError("each message must be an object")
    role = message.get("role")
    if role not in {"system", "developer", "user", "assistant", "tool"}:
        raise ValueError("message role must be system, developer, user, assistant, or tool")
    return {"role": role, "content": content_text(message.get("content", ""))}


def carve_context(messages: list[dict[str, str]]) -> list[dict[str, str]]:
    """Preserve instructions and the active turn while carving stale history."""
    if len(messages) <= 2:
        return messages

    protected: list[dict[str, str]] = []
    seen_instruction_text: set[str] = set()
    for message in messages:
        if message["role"] not in {"system", "developer"}:
            continue
        normalized = " ".join(message["content"].split())
        if normalized and normalized not in seen_instruction_text:
            protected.append({"role": message["role"], "content": normalized})
            seen_instruction_text.add(normalized)

    # Starting on Turn 2, discard historical assistant turns and duplicate
    # user context. The active user turn is the only conversational slice
    # needed for this audit proxy; the full history remains in the baseline.
    active = next(
        (message for message in reversed(messages) if message["role"] not in {"system", "developer"}),
        None,
    )
    if active is None:
        return protected
    return protected + [{
        "role": active["role"],
        "content": " ".join(active["content"].split()),
    }]


def raw_prompt(messages: list[dict[str, str]]) -> str:
    return "\n".join(f"{message['role'].upper()}: {message['content']}" for message in messages)


def compact_prompt(messages: list[dict[str, str]]) -> str:
    return "\n".join(
        f"{message['role'].upper()}: {' '.join(message['content'].split())}"
        for message in messages
    )


def live_provider_dispatch(prompt: str) -> str:
    """Use the project's Vertex path when configured; retain legacy fallback."""
    if os.environ.get("GCP_SERVICE_ACCOUNT"):
        bridge = r"""
import fs from "node:fs";
import { generateVertexText } from "./src/geminiVertex.ts";
const input = JSON.parse(fs.readFileSync(0, "utf8"));
(async () => {
  const text = await generateVertexText(input.prompt, {
    maxOutputTokens: 512,
    temperature: 0.4,
    thinkingConfig: { thinkingBudget: 0 },
  });
  console.log(JSON.stringify({ text }));
})().catch((error) => {
  console.error(error);
  process.exit(1);
});
"""
        result = subprocess.run(
            ["pnpm", "--dir", "artifacts/api-server", "exec", "tsx", "--eval", bridge],
            input=json.dumps({"prompt": prompt}),
            capture_output=True,
            text=True,
            timeout=90,
            check=False,
        )
        if result.returncode != 0:
            raise RuntimeError(result.stderr.strip()[-500:])
        try:
            response = json.loads(result.stdout.strip().splitlines()[-1])
        except (json.JSONDecodeError, IndexError) as error:
            raise RuntimeError("Vertex bridge returned invalid JSON") from error
        text = response.get("text")
        if not isinstance(text, str) or not text.strip():
            raise RuntimeError("Vertex returned no generated content")
        return text.strip()
    return gemini_dispatch(prompt, {"provided": False})


class CustomerZeroHandler(BaseHTTPRequestHandler):
    server_version = "GKA-CustomerZero/2.0"

    def send_json(self, status: int, payload: dict[str, object], headers: dict[str, str] | None = None) -> None:
        body = json.dumps(payload, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        for key, value in (headers or {}).items():
            self.send_header(key, value)
        self.end_headers()
        self.wfile.write(body)

    def do_GET(self) -> None:
        if self.path == "/healthz":
            self.send_json(200, {
                "status": "ok",
                "kernel": "Morris Law Kernel V2",
                "gka": GKA_CORE.verify_parity(),
            })
            return
        self.send_error(404, "Not Found")

    def do_POST(self) -> None:
        if self.path != "/v1/chat/completions":
            self.send_error(404, "Not Found")
            return

        started = perf_counter()
        try:
            length = int(self.headers.get("Content-Length", "0"))
            if length <= 0 or length > 2_000_000:
                raise ValueError("JSON request body is required and must be under 2 MB")
            payload = json.loads(self.rfile.read(length))
            if not isinstance(payload, dict) or not isinstance(payload.get("messages"), list):
                raise ValueError("messages must be an array")

            messages = [normalize_message(message) for message in payload["messages"]]
            carved_messages = carve_context(messages)
            response_schema = payload.get("response_format")
            schema_context = (
                f"\nRESPONSE_FORMAT: {json.dumps(response_schema, separators=(',', ':'), ensure_ascii=False)}"
                if response_schema is not None
                else ""
            )
            raw_prompt_text = raw_prompt(messages)
            raw_context = raw_prompt_text + schema_context
            carved_prompt = compact_prompt(carved_messages) + schema_context
            baseline_tokens = estimate_tokens(raw_context)
            processed_tokens = estimate_tokens(carved_prompt)
            suppressed_tokens = max(0, baseline_tokens - processed_tokens)
            suppression_rate = (
                (suppressed_tokens / baseline_tokens) * 100
                if baseline_tokens else 0.0
            )
            overhead_ms = (perf_counter() - started) * 1000

            provider_prompt = (
                "You are the live Customer Zero response engine behind a GKA "
                "OpenAI-compatible proxy. Answer the active user request directly "
                "and concisely. Do not mention internal telemetry.\n\n"
                f"{carved_prompt}"
            )
            completion = live_provider_dispatch(provider_prompt)
            completion_tokens = estimate_tokens(completion)

            telemetry_headers = {
                "X-GKA-Baseline-Tokens": str(baseline_tokens),
                "X-GKA-Processed-Tokens": str(processed_tokens),
                "X-GKA-Tokens-Suppressed": str(suppressed_tokens),
                "X-GKA-Suppression-Rate": f"{suppression_rate:.2f}%",
                "X-GKA-Latency-Overhead-MS": f"{overhead_ms:.4f}",
            }
            self.send_json(200, {
                "id": f"chatcmpl-gka-{uuid4().hex[:16]}",
                "object": "chat.completion",
                "created": int(__import__("time").time()),
                "model": payload.get("model", "gka-gemini-live"),
                "choices": [{
                    "index": 0,
                    "message": {"role": "assistant", "content": completion},
                    "finish_reason": "stop",
                }],
                "usage": {
                    "prompt_tokens": processed_tokens,
                    "completion_tokens": completion_tokens,
                    "total_tokens": processed_tokens + completion_tokens,
                },
                "gka": {
                    "baseline_tokens": baseline_tokens,
                    "processed_tokens": processed_tokens,
                    "tokens_suppressed": suppressed_tokens,
                    "suppression_rate": round(suppression_rate, 2),
                    "latency_overhead_ms": round(overhead_ms, 4),
                    "parity": GKA_CORE.verify_parity(),
                },
            }, telemetry_headers)
        except ValueError as error:
            self.send_json(400, {"error": {"type": "invalid_request_error", "message": str(error)}})
        except Exception as error:
            print(f"[gka-customer-zero] provider failure: {error}", flush=True)
            self.send_json(502, {"error": {"type": "upstream_error", "message": "Live provider request failed."}})

    def log_message(self, format: str, *args: object) -> None:
        print(f"[gka-customer-zero] {format % args}", flush=True)


if __name__ == "__main__":
    port = int(os.environ.get("GKA_PROXY_PORT", "8090"))
    server = ThreadingHTTPServer(("127.0.0.1", port), CustomerZeroHandler)
    print(f"GKA Customer Zero proxy listening on http://127.0.0.1:{port}", flush=True)
    server.serve_forever()

import express, { type Express, type Request, type Response, type NextFunction } from "express";
import cors from "cors";
import cookieParser from "cookie-parser";
import pinoHttp from "pino-http";
import { clerkMiddleware } from "@clerk/express";
import { publishableKeyFromHost } from "@clerk/shared/keys";
import router from "./routes";
import { recoverStaleMasterJobs } from "./routes/master";
import { logger } from "./lib/logger";
import { loadAuthUser } from "./middlewares/authMiddleware";
import { maintenanceModeMiddleware } from "./middlewares/maintenanceMode";
import { WebhookHandlers } from "./webhookHandlers";
import {
  CLERK_PROXY_PATH,
  clerkProxyMiddleware,
  getClerkProxyHost,
} from "./middlewares/clerkProxyMiddleware";

// Log crashes before the process dies — helps diagnose production "Processing failed" with no log entry.
process.on("uncaughtException", (err) => logger.fatal({ err }, "uncaughtException"));
process.on("unhandledRejection", (reason) => logger.fatal({ reason }, "unhandledRejection"));

const app: Express = express();

// In-process mastering cannot resume once its /tmp input disappears at a
// restart. Recover stale records early so clients can retry instead of polling
// "running" forever. A not-yet-published schema must not prevent boot.
void recoverStaleMasterJobs().catch((err) => {
  logger.warn({ err }, "unable to recover stale mastering jobs");
});

// Stamp request arrival so routes can report true server-side handler time
// (health.ts serverMs, master.ts X-GK-Timing-* headers).
app.use((_req: Request, res: Response, next: NextFunction) => {
  res.locals.requestStartMs = performance.now();
  next();
});

app.use(
  pinoHttp({
    logger,
    serializers: {
      req(req) {
        return { id: req.id, method: req.method, url: req.url?.split("?")[0] };
      },
      res(res) {
        return { statusCode: res.statusCode };
      },
    },
  }),
);

// Clerk proxy MUST be mounted before body parsers — it streams raw bytes.
app.use(CLERK_PROXY_PATH, clerkProxyMiddleware());

// Webhook route MUST be registered before express.json() so the raw Buffer body is preserved
app.post(
  "/api/stripe/webhook",
  express.raw({ type: "application/json" }),
  async (req, res) => {
    const signature = req.headers["stripe-signature"];
    if (!signature) {
      res.status(400).json({ error: "Missing stripe-signature header" });
      return;
    }

    const sig = Array.isArray(signature) ? signature[0] : signature;

    try {
      await WebhookHandlers.processWebhook(req.body as Buffer, sig, req);
      res.status(200).json({ received: true });
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : "Unknown error";
      logger.error({ err }, "Webhook processing error");
      res.status(400).json({ error: message });
    }
  },
);

// Build an exact-match allowlist from REPLIT_DOMAINS (comma-separated in prod).
// Also include the Replit dev domain and Expo web preview domain for development.
// In development any localhost / 127.0.0.1 origin is also permitted.
const trustedOrigins: Set<string> = new Set(
  [
    ...(process.env.REPLIT_DOMAINS ?? "").split(",").map(d => d.trim()).filter(Boolean).map(d => `https://${d}`),
    process.env.REPLIT_DEV_DOMAIN ? `https://${process.env.REPLIT_DEV_DOMAIN}` : null,
    // Expo web preview: <id>.expo.<host> — derived from REPLIT_EXPO_DEV_DOMAIN
    process.env.REPLIT_EXPO_DEV_DOMAIN ? `https://${process.env.REPLIT_EXPO_DEV_DOMAIN}` : null,
  ].filter((d): d is string => typeof d === "string"),
);

app.use(
  cors({
    credentials: true,
    origin(requestOrigin, callback) {
      // Same-origin and server-to-server requests have no Origin header — allow.
      if (!requestOrigin) return callback(null, true);
      // Exact match against the allowlist.
      if (trustedOrigins.has(requestOrigin)) return callback(null, true);
      // Permit localhost in development only.
      if (
        process.env.NODE_ENV !== "production" &&
        /^https?:\/\/(localhost|127\.0\.0\.1)(:\d+)?$/.test(requestOrigin)
      ) {
        return callback(null, true);
      }
      callback(new Error(`CORS: origin not allowed: ${requestOrigin}`));
    },
  }),
);
app.use(cookieParser());
// JAX enterprise sessions may intentionally retransmit a multi-file codebase
// and accumulated diagnostics on every turn. Keep this aligned with the GKA
// proxy's 2 MB request ceiling while preserving an explicit finite limit.
app.use(express.json({ limit: "2mb" }));
app.use(express.urlencoded({ extended: true }));

// Clerk session validation — resolves the publishable key from the request host
// so the same server can handle multiple custom domains.
app.use(
  clerkMiddleware((req) => ({
    publishableKey: publishableKeyFromHost(
      getClerkProxyHost(req) ?? "",
      process.env.CLERK_PUBLISHABLE_KEY,
    ),
  })),
);

// Load authenticated user into req.dbUser (optional — does not reject requests).
app.use(loadAuthUser);
app.use(maintenanceModeMiddleware);

app.use("/api", router);

// Global JSON error handler — MUST be last. Catches any error passed to next(err)
// (multer LIMIT_FILE_SIZE, CORS failures, unhandled route errors, etc.) and returns
// JSON instead of Express's default HTML page, which the client can't parse and
// shows as a generic "Processing failed" with no useful message.
// eslint-disable-next-line @typescript-eslint/no-unused-vars
app.use((err: Error, _req: Request, res: Response, _next: NextFunction): void => {
  const status = (err as { status?: number; statusCode?: number }).status
    ?? (err as { status?: number; statusCode?: number }).statusCode
    ?? 500;
  logger.error({ err }, "unhandled express error");
  if (!res.headersSent) {
    res.status(status).json({ success: false, error: err.message ?? "Internal server error" });
  }
});

export default app;

import app from "./app";
import { logger } from "./lib/logger";
import { runMigrations } from "stripe-replit-sync";
import { getStripeSync } from "./stripeClient";
import { ensureStripeProducts } from "./lib/stripeProducts";
import { submitSitemapToGSC } from "./lib/googleSearchConsole";
import { scheduleOverdueAlerts } from "./lib/investorAlerts";
import { scheduleInvestorOutreachDispatcher } from "./lib/investorOutreach";
import { scheduleIndexNowSubmission } from "./lib/indexNow";
import { scheduleTelemetryReports } from "./lib/telemetryReports";
import { db } from "@workspace/db";
import { usersTable } from "@workspace/db";
import { sql } from "drizzle-orm";
import { DEMO_EMAIL, DEMO_PASSWORD_HASH, DEMO_USER_ID } from "./lib/auth";

const rawPort = process.env["PORT"];

if (!rawPort) {
  throw new Error("PORT environment variable is required but was not provided.");
}

const port = Number(rawPort);
if (Number.isNaN(port) || port <= 0) {
  throw new Error(`Invalid PORT value: "${rawPort}"`);
}

/**
 * Sets up the Stripe managed webhook, with automatic self-healing.
 *
 * stripe-replit-sync stores the Stripe webhook endpoint ID in
 * stripe._managed_webhooks.  If that endpoint is later deleted from the
 * Stripe dashboard (or after a re-publish pointing to a new domain), the
 * stored ID becomes stale and findOrCreateManagedWebhook throws
 * StripeInvalidRequestError code=resource_missing.
 *
 * When that happens we delete the stale DB row and retry once, so the server
 * always comes up with a valid, live webhook — no manual intervention required.
 */
async function setupWebhook(webhookUrl: string): Promise<void> {
  const stripeSync = await getStripeSync();

  try {
    await stripeSync.findOrCreateManagedWebhook(webhookUrl);
    logger.info({ url: webhookUrl }, "Webhook configured");
  } catch (err: unknown) {
    const isResourceMissing =
      err instanceof Error &&
      "code" in err &&
      (err as { code: string }).code === "resource_missing";

    if (!isResourceMissing) throw err;

    // The stored webhook endpoint no longer exists in Stripe.
    // Wipe the stale row so findOrCreateManagedWebhook creates a fresh one.
    logger.warn(
      { url: webhookUrl },
      "Stale webhook endpoint detected — clearing and recreating automatically"
    );

    await db.execute(
      sql`DELETE FROM stripe._managed_webhooks WHERE url = ${webhookUrl}`
    );

    // Retry — this time findOrCreateManagedWebhook will INSERT a fresh record.
    await stripeSync.findOrCreateManagedWebhook(webhookUrl);
    logger.info({ url: webhookUrl }, "Webhook recreated successfully");
  }
}

async function initStripe() {
  const databaseUrl = process.env.DATABASE_URL;

  if (!databaseUrl) {
    logger.warn("DATABASE_URL not set — skipping Stripe initialization");
    return;
  }

  try {
    logger.info("Running Stripe schema migrations...");
    await runMigrations({ databaseUrl });
    logger.info("Stripe schema ready");
  } catch (err: unknown) {
    logger.error({ err }, "Stripe migrations failed");
    return;
  }

  try {
    const domain = process.env.REPLIT_DOMAINS?.split(",")[0]?.trim();
    const webhookUrl = `https://${domain}/api/stripe/webhook`;
    logger.info({ url: webhookUrl }, "Setting up managed webhook...");
    await setupWebhook(webhookUrl);

    // Self-seed the product catalog BEFORE the backfill so a freshly connected
    // live account (publish-time Stripe step) mirrors complete products/prices.
    try {
      await ensureStripeProducts();
    } catch (err: unknown) {
      logger.error({ err }, "Stripe product self-seed failed");
    }

    logger.info("Starting Stripe data backfill (runs in background)...");
    const stripeSync = await getStripeSync();
    stripeSync
      // Passing no argument makes syncBackfill a silent no-op in this library
      // version (the object selector falls through the switch). "all" performs
      // the real product/price/customer/subscription backfill.
      .syncBackfill({ object: "all" })
      .then(() => logger.info("Stripe data backfill complete"))
      .catch((err: unknown) => {
        // Known benign case: the local mirror still carries customer IDs
        // minted on a previously connected Stripe account (dev sandbox before
        // the live account was attached). Listing payment methods for those
        // throws resource_missing. Checkout self-heals such customers via
        // ensureCustomerOnCurrentAccount, so log this quietly instead of as
        // an ERROR that buries real backfill failures.
        const e = err as { code?: string; param?: string };
        if (e?.code === "resource_missing" && e?.param === "customer") {
          logger.warn(
            { err },
            "Stripe backfill skipped stale mirrored customer(s) from a previously connected account — checkout self-heals these"
          );
          return;
        }
        logger.error({ err }, "Stripe backfill error");
      });
  } catch (err: unknown) {
    logger.error({ err }, "Failed to set up Stripe webhook/backfill");
  }
}

async function migrateAppSchema() {
  try {
    await db.execute(sql`
      ALTER TABLE users
        ADD COLUMN IF NOT EXISTS password_hash text
    `);
    await db.execute(sql`
      ALTER TABLE users
        ADD COLUMN IF NOT EXISTS credits_balance integer NOT NULL DEFAULT 0
    `);
    await db.execute(sql`
      CREATE TABLE IF NOT EXISTS credit_transactions (
        id                       varchar     PRIMARY KEY DEFAULT gen_random_uuid(),
        user_id                  varchar     NOT NULL REFERENCES users(id) ON DELETE CASCADE,
        delta                    integer     NOT NULL,
        kind                     text        NOT NULL,
        reference                text,
        stripe_payment_intent_id text,
        created_at               timestamptz NOT NULL DEFAULT now()
      )
    `);
    await db.execute(sql`
      CREATE INDEX IF NOT EXISTS credit_transactions_user_created_idx
        ON credit_transactions(user_id, created_at)
    `);
    await db.execute(sql`
      CREATE UNIQUE INDEX IF NOT EXISTS credit_transactions_reference_idx
        ON credit_transactions(reference)
    `);
    await db.execute(sql`
      CREATE UNIQUE INDEX IF NOT EXISTS credit_transactions_stripe_intent_idx
        ON credit_transactions(stripe_payment_intent_id)
    `);

    // One-time owner wallet initialization. The fixed ledger reference makes
    // this safe across restarts and guarantees it never becomes an auto-refill.
    await db.execute(sql`
      WITH owner AS (
        SELECT id, credits_balance
        FROM users
        WHERE lower(email) = 'allnonellc0120@gmail.com'
        LIMIT 1
      ),
      adjustment AS (
        INSERT INTO credit_transactions (user_id, delta, kind, reference)
        SELECT
          id,
          5000 - credits_balance,
          'admin_balance_set',
          'owner-admin-initial-balance-5000'
        FROM owner
        WHERE credits_balance <> 5000
        ON CONFLICT (reference) DO NOTHING
        RETURNING user_id, delta
      )
      UPDATE users
      SET credits_balance = users.credits_balance + adjustment.delta
      FROM adjustment
      WHERE users.id = adjustment.user_id
    `);
    await db.execute(sql`
      ALTER TABLE lyric_projects
        ADD COLUMN IF NOT EXISTS mode              text        NOT NULL DEFAULT 'simple',
        ADD COLUMN IF NOT EXISTS story_prompt      text,
        ADD COLUMN IF NOT EXISTS key               text,
        ADD COLUMN IF NOT EXISTS vocal_type        text,
        ADD COLUMN IF NOT EXISTS genre_tags        text,
        ADD COLUMN IF NOT EXISTS lines_state       jsonb,
        ADD COLUMN IF NOT EXISTS style_prompt      text,
        ADD COLUMN IF NOT EXISTS generation_count  integer     DEFAULT 1,
        ADD COLUMN IF NOT EXISTS is_locked         boolean     DEFAULT false
    `);

    await db.execute(sql`
      ALTER TABLE lyric_revisions
        ADD COLUMN IF NOT EXISTS edit_type          text,
        ADD COLUMN IF NOT EXISTS line_index         integer,
        ADD COLUMN IF NOT EXISTS original_line_text text,
        ADD COLUMN IF NOT EXISTS regen_instruction  text
    `);

    // Generated tracks now persist the sung lyrics for the library player
    // (owner-only exposure). Additive + idempotent so databases created
    // before this column upgrade safely on startup.
    await db.execute(sql`
      ALTER TABLE tracks
        ADD COLUMN IF NOT EXISTS lyrics_text text
    `);

    await db.execute(sql`
      ALTER TABLE purchased_tracks
        ADD COLUMN IF NOT EXISTS is_pinned boolean NOT NULL DEFAULT false
    `);

    await db.execute(sql`
      ALTER TABLE users
        ADD COLUMN IF NOT EXISTS profile_bio text
    `);

    await db.execute(sql`
      CREATE TABLE IF NOT EXISTS lyric_timeline_blocks (
        id             text        PRIMARY KEY,
        project_id     text        NOT NULL REFERENCES lyric_projects(id) ON DELETE CASCADE,
        timestamp_ms   integer     NOT NULL DEFAULT 0,
        label          text        NOT NULL,
        section_type   text,
        sort_order     integer     NOT NULL DEFAULT 0,
        created_at     timestamptz NOT NULL DEFAULT now()
      )
    `);

    await db.execute(sql`
      CREATE TABLE IF NOT EXISTS lyric_forensic_ledger (
        id                       text        PRIMARY KEY,
        project_id               text        NOT NULL REFERENCES lyric_projects(id) ON DELETE CASCADE,
        session_id               text,
        edit_type                text        NOT NULL,
        line_index               integer,
        original_text            text,
        new_text                 text,
        regen_instruction        text,
        levenshtein_delta        integer,
        authorship_score_before  integer,
        authorship_score_after   integer,
        created_at               timestamptz NOT NULL DEFAULT now()
      )
    `);

    await db.execute(sql`
      CREATE TABLE IF NOT EXISTS ip_cert_stubs (
        cert_id               text        PRIMARY KEY,
        denominator           text        NOT NULL,
        handshake             text        NOT NULL,
        content_hash          text        NOT NULL,
        artist                text        NOT NULL,
        certified_at          timestamptz NOT NULL DEFAULT now(),
        style_prompt          text,
        style_authorship_score integer
      )
    `);

    // Certificate paywall — docs stay private until unlocked (additive + idempotent).
    await db.execute(sql`
      ALTER TABLE ip_cert_stubs
        ADD COLUMN IF NOT EXISTS ipi_number        text,
        ADD COLUMN IF NOT EXISTS iswc              text,
        ADD COLUMN IF NOT EXISTS isrc              text,
        ADD COLUMN IF NOT EXISTS owner_user_id     text,
        ADD COLUMN IF NOT EXISTS category          text,
        ADD COLUMN IF NOT EXISTS provenance        text,
        ADD COLUMN IF NOT EXISTS unlocked_at       timestamptz,
        ADD COLUMN IF NOT EXISTS unlock_source     text,
        ADD COLUMN IF NOT EXISTS stripe_session_id text
    `);
    // Provenance attribution on the certificate document — the generating AI
    // model and the commercial-catalog copyright-screen result (additive +
    // idempotent; NULL on legacy stubs → fields omitted from the document).
    await db.execute(sql`
      ALTER TABLE ip_cert_stubs
        ADD COLUMN IF NOT EXISTS generation_model       text,
        ADD COLUMN IF NOT EXISTS fingerprint_status     text,
        ADD COLUMN IF NOT EXISTS fingerprint_provider   text,
        ADD COLUMN IF NOT EXISTS fingerprint_scanned_at timestamptz
    `);
    await db.execute(sql`
      ALTER TABLE users
        ADD COLUMN IF NOT EXISTS cert_unlocks             integer NOT NULL DEFAULT 0,
        ADD COLUMN IF NOT EXISTS cert_unlock_period_start timestamptz
    `);
    // `pro` historically meant the higher Studio entitlement. Migrate those
    // rows before `pro` is reused for the new $9.99 plan, preventing an
    // existing lifetime/manual grant from being silently downgraded.
    await db.execute(sql`
      WITH migration_marker AS (
        INSERT INTO admin_settings (key, value)
        VALUES ('migration.legacy_pro_to_king', 'complete')
        ON CONFLICT (key) DO NOTHING
        RETURNING key
      )
      UPDATE users
      SET subscription_tier = 'king'
      WHERE subscription_tier = 'pro'
        AND EXISTS (SELECT 1 FROM migration_marker)
    `);

    // Investor outreach tracker (admin-only).
    await db.execute(sql`
      CREATE TABLE IF NOT EXISTS investor_prospects (
        id          uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
        sort_order  integer     NOT NULL DEFAULT 0,
        name        text        NOT NULL,
        route       text,
        notes       text,
        status      text        NOT NULL DEFAULT 'not_started',
        created_at  timestamptz NOT NULL DEFAULT now(),
        updated_at  timestamptz NOT NULL DEFAULT now()
      )
    `);
    // sort_order is the seed identity — unique constraint lets onConflictDoNothing
    // prevent duplicate prospect sets from concurrent first-load requests.
    // Use a DO block because ADD CONSTRAINT IF NOT EXISTS is not standard SQL.
    await db.execute(sql`
      DO $$
      BEGIN
        IF NOT EXISTS (
          SELECT 1 FROM pg_constraint WHERE conname = 'investor_prospects_sort_order_uniq'
        ) THEN
          ALTER TABLE investor_prospects
            ADD CONSTRAINT investor_prospects_sort_order_uniq UNIQUE (sort_order);
        END IF;
      END $$
    `);
    await db.execute(sql`
      CREATE TABLE IF NOT EXISTS investor_touches (
        id           uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
        prospect_id  uuid        NOT NULL REFERENCES investor_prospects(id) ON DELETE CASCADE,
        touch_number integer     NOT NULL,
        sent_at      date,
        response     text,
        notes        text,
        created_at   timestamptz NOT NULL DEFAULT now(),
        updated_at   timestamptz NOT NULL DEFAULT now(),
        UNIQUE (prospect_id, touch_number)
      )
    `);
    // Partner promo attribution. A referred account can redeem a campaign
    // code once; paid-invoice handling changes applied -> converted.
    await db.execute(sql`
      CREATE TABLE IF NOT EXISTS promo_referrals (
        id                uuid PRIMARY KEY DEFAULT gen_random_uuid(),
        referrer_name     text NOT NULL,
        referred_user_id  varchar NOT NULL REFERENCES users(id) ON DELETE CASCADE,
        promo_code_used   text NOT NULL,
        status            text NOT NULL DEFAULT 'applied',
        created_at        timestamptz NOT NULL DEFAULT now(),
        converted_at      timestamptz,
        stripe_invoice_id text
      )
    `);
    await db.execute(sql`
      CREATE UNIQUE INDEX IF NOT EXISTS promo_referrals_user_code_unique
        ON promo_referrals(referred_user_id, promo_code_used)
    `);
    await db.execute(sql`
      CREATE INDEX IF NOT EXISTS promo_referrals_code_status_idx
        ON promo_referrals(promo_code_used, status)
    `);
    await db.execute(sql`
      CREATE TABLE IF NOT EXISTS generation_jobs (
        id varchar(64) PRIMARY KEY,
        user_id text NOT NULL,
        status varchar(32) NOT NULL DEFAULT 'queued',
        current_stage integer NOT NULL DEFAULT 1,
        progress_percent integer NOT NULL DEFAULT 0,
        lyrics text,
        style_prompt text,
        original_audio_url text,
        demucs_vocal_url text,
        demucs_instrumental_url text,
        rvc_vocal_url text,
        final_master_wav_url text,
        final_master_mp3_url text,
        error_message text,
        created_at timestamptz NOT NULL DEFAULT now(),
        updated_at timestamptz NOT NULL DEFAULT now()
      )
    `);
    await db.execute(sql`
      CREATE INDEX IF NOT EXISTS generation_jobs_user_created_idx
        ON generation_jobs(user_id, created_at)
    `);

    logger.info("App schema migration complete");
  } catch (err: unknown) {
    logger.error({ err }, "App schema migration failed — continuing anyway");
  }
}

