import { Router, type Request, type Response } from "express";
import { rateLimit } from "../lib/rateLimiter";
import { resolveTelemetryClient } from "../lib/liveTelemetryConfig";
import {
  getTokenTelemetryLedgerSummary,
  readTokenTelemetryLedger,
} from "../middleware/tokenTracker";

const telemetryRouter = Router();
const DEFAULT_RECORD_LIMIT = 100;
const MAX_RECORD_LIMIT = 500;

function capabilityToken(req: Request): string {
  if (typeof req.query.token === "string") return req.query.token;
  const authorization = req.header("authorization") ?? "";
  return authorization.startsWith("Bearer ") ? authorization.slice(7) : "";
}

function recordLimit(req: Request): number {
  const requested = Number(req.query.limit);
  if (!Number.isInteger(requested) || requested <= 0) return DEFAULT_RECORD_LIMIT;
  return Math.min(requested, MAX_RECORD_LIMIT);
}

telemetryRouter.get(
  "/telemetry/live",
  rateLimit({ windowMs: 60_000, max: 60 }),
  async (req: Request, res: Response) => {
    res.setHeader("Cache-Control", "no-store, private");
    const token = capabilityToken(req);
    if (!token.trim()) {
      res.status(401).json({ error: "Unauthorized" });
      return;
    }

    const client = resolveTelemetryClient(token);
    if (!client) {
      res.status(401).json({ error: "Unauthorized" });
      return;
    }

    try {
      // Both reads are explicitly scoped. Never call either helper without the
      // capability-mapped client ID from this route.
      const [summary, clientRecords] = await Promise.all([
        getTokenTelemetryLedgerSummary(client.clientId),
        readTokenTelemetryLedger(client.clientId),
      ]);
      const limit = recordLimit(req);
      res.json({
        clientId: client.clientId,
        generatedAt: new Date().toISOString(),
        summary,
        records: clientRecords.slice(-limit),
      });
    } catch (error) {
      req.log.error({ error }, "Live token telemetry read failed");
      res.status(500).json({ error: "Token telemetry is unavailable." });
    }
  },
);

export default telemetryRouter;

import type { Request, Response, NextFunction } from "express";
import { randomUUID } from "crypto";
import { performance } from "perf_hooks";
import { appendFile, mkdir, readFile } from "node:fs/promises";
import path from "node:path";
import { getEncoding } from "js-tiktoken";

export type TokenTelemetryRecord = {
  id: string;
  operation: "jax_generate" | "jax_remix" | "simulation";
  client_id: string | null;
  prompt_tokens: number;
  completion_tokens: number;
  raw_prompt_tokens: number;
  processed_prompt_tokens: number;
  raw_tokens_baseline: number;
  actual_tokens_used: number;
  tokens_suppressed: number;
  suppression_percentage: number;
  token_rate_per_million_usd: number;
  dollar_savings: number;
  gka_gain_share_due: number;
  latency_overhead_ms: number;
  provider?: string;
  status: "completed" | "failed";
  created_at: string;
};

export type TokenTelemetryInput = {
  operation: TokenTelemetryRecord["operation"];
  rawBaselineText: string;
  actualPromptText: string;
  maxOutputTokens?: number;
  provider?: string;
  clientId?: string;
  modelRatePerMillionUsd?: number;
};

const MAX_LEDGER_RECORDS = 10_000;
const DEFAULT_TOKEN_RATE_PER_MILLION_USD = 2.5;
const GKA_GAIN_SHARE_RATE = 0.33;
const tokenEncoding = getEncoding("cl100k_base");
const ledger: TokenTelemetryRecord[] = [];
let nextRecordId = 1;
let ledgerWriteQueue: Promise<void> = Promise.resolve();

function defaultLedgerPath(): string {
  const workingDirectory = process.cwd();
  const artifactRoot =
    path.basename(workingDirectory) === "api-server"
      ? workingDirectory
      : path.resolve(workingDirectory, "artifacts/api-server");
  return path.resolve(artifactRoot, "data/token_savings_ledger.jsonl");
}

export const TOKEN_LEDGER_PATH =
  process.env.GKA_TOKEN_LEDGER_PATH?.trim() || defaultLedgerPath();

/**
 * Exact cl100k_base BPE tokenization used for the current model-cost ledger.
 * The encoder is cached once per process so request bookkeeping stays cheap.
 */
export function countTokens(text: string): number {
  return tokenEncoding.encode(text).length;
}

function persistRecord(record: TokenTelemetryRecord): TokenTelemetryRecord {
  ledger.push(record);
  if (ledger.length > MAX_LEDGER_RECORDS) ledger.splice(0, ledger.length - MAX_LEDGER_RECORDS);
  ledgerWriteQueue = ledgerWriteQueue
    .then(async () => {
      await mkdir(path.dirname(TOKEN_LEDGER_PATH), { recursive: true });
      await appendFile(TOKEN_LEDGER_PATH, `${JSON.stringify(record)}\n`, "utf8");
    })
    .catch((error: unknown) => {
      console.error("Token telemetry ledger append failed", {
        error,
        ledgerPath: TOKEN_LEDGER_PATH,
        recordId: record.id,
      });
    });
  return record;
}

export function getTokenTelemetryLedger(): readonly TokenTelemetryRecord[] {
  return ledger;
}

export function clearTokenTelemetryLedger(): void {
  ledger.length = 0;
}

export async function flushTokenTelemetryLedger(): Promise<void> {
  await ledgerWriteQueue;
}

function isFileNotFound(error: unknown): boolean {
  return Boolean(
    error &&
      typeof error === "object" &&
      "code" in error &&
      (error as { code?: unknown }).code === "ENOENT",
  );
}

export async function readTokenTelemetryLedger(
  clientId?: string,
): Promise<TokenTelemetryRecord[]> {
  await flushTokenTelemetryLedger();

  let contents: string;
  try {
    contents = await readFile(TOKEN_LEDGER_PATH, "utf8");
  } catch (error) {
    if (isFileNotFound(error)) return [];
    throw error;
  }

  const records = contents
    .split(/\r?\n/)
    .map((line, index) => ({ line: line.trim(), index }))
    .filter(({ line }) => line.length > 0)
    .map(({ line, index }) => {
      try {
        return JSON.parse(line) as TokenTelemetryRecord;
      } catch (error) {
        throw new Error(`Invalid token telemetry ledger record at line ${index + 1}`, {
          cause: error,
        });
      }
    });

  return clientId ? records.filter((record) => record.client_id === clientId) : records;
}

function roundMoney(value: number): number {
  return Number(value.toFixed(6));
}

export async function getTokenTelemetryLedgerSummary(clientId?: string) {
  const records = await readTokenTelemetryLedger(clientId);
  const totals = records.reduce(
    (summary, record) => {
      summary.totalRawTokens += record.raw_prompt_tokens ?? record.raw_tokens_baseline;
      summary.totalCarvedTokens += record.processed_prompt_tokens ?? record.prompt_tokens;
      summary.totalTokensSuppressed += record.tokens_suppressed;
      summary.totalDollarsSaved += record.dollar_savings ?? 0;
      summary.totalGkaGainShareDue += record.gka_gain_share_due ?? 0;
      return summary;
    },
    {
      totalRawTokens: 0,
      totalCarvedTokens: 0,
      totalTokensSuppressed: 0,
      totalDollarsSaved: 0,
      totalGkaGainShareDue: 0,
    },
  );

  return {
    clientId: clientId ?? null,
    recordCount: records.length,
    totalRawTokens: totals.totalRawTokens,
    totalCarvedTokens: totals.totalCarvedTokens,
    totalTokensSuppressed: totals.totalTokensSuppressed,
    totalDollarsSaved: roundMoney(totals.totalDollarsSaved),
    totalGkaGainShareDue: roundMoney(totals.totalGkaGainShareDue),
  };
}

export function recordTokenTelemetry(
  input: TokenTelemetryInput & {
    completionText: string;
    status?: TokenTelemetryRecord["status"];
    startedAt?: number;
  },
): TokenTelemetryRecord {
  const startedAt = input.startedAt ?? performance.now();
  const promptTokens = countTokens(input.actualPromptText);
  const completionTokens = countTokens(input.completionText);
  const rawPromptTokens = countTokens(input.rawBaselineText);
  const tokensSuppressed = Math.max(0, rawPromptTokens - promptTokens);
  const configuredTokenRate = Number(process.env.GKA_TOKEN_RATE_PER_MILLION_USD);
  const tokenRatePerMillionUsd =
    Number.isFinite(input.modelRatePerMillionUsd) && (input.modelRatePerMillionUsd ?? 0) >= 0
      ? input.modelRatePerMillionUsd!
      : Number.isFinite(configuredTokenRate) && configuredTokenRate >= 0
        ? configuredTokenRate
        : DEFAULT_TOKEN_RATE_PER_MILLION_USD;
  const dollarSavings = roundMoney((tokensSuppressed / 1_000_000) * tokenRatePerMillionUsd);

  const record = {
    id: `gka-token-${nextRecordId++}`,
    operation: input.operation,
    client_id: input.clientId ?? null,
    prompt_tokens: promptTokens,
    completion_tokens: completionTokens,
    raw_prompt_tokens: rawPromptTokens,
    processed_prompt_tokens: promptTokens,
    raw_tokens_baseline: rawPromptTokens,
    actual_tokens_used: promptTokens + completionTokens,
    tokens_suppressed: tokensSuppressed,
    suppression_percentage: rawPromptTokens > 0
      ? Number(((tokensSuppressed / rawPromptTokens) * 100).toFixed(2))
      : 0,
    token_rate_per_million_usd: tokenRatePerMillionUsd,
    dollar_savings: dollarSavings,
    gka_gain_share_due: roundMoney(dollarSavings * GKA_GAIN_SHARE_RATE),
    latency_overhead_ms: 0,
    provider: input.provider,
    status: input.status ?? "completed",
    created_at: new Date().toISOString(),
  } satisfies TokenTelemetryRecord;
  persistRecord(record);
  record.latency_overhead_ms = Number((performance.now() - startedAt).toFixed(4));
  return record;
}

export type TokenTracker = {
  finish: (completionText: string, options?: {
    provider?: string;
    status?: TokenTelemetryRecord["status"];
  }) => TokenTelemetryRecord;
  record?: TokenTelemetryRecord;
};

export function beginTokenTracking(input: TokenTelemetryInput): TokenTracker {
  let record: TokenTelemetryRecord | undefined;
  return {
    finish(completionText, options = {}) {
      if (record) return record;
      record = recordTokenTelemetry({
        ...input,
        completionText,
        // Start after the provider returns so this measures only telemetry
        // bookkeeping, never model execution latency.
        startedAt: performance.now(),
        provider: options.provider ?? input.provider,
        status: options.status,
      });
      return record;
    },
    get record() {
      return record;
    },
  };
}

/**
 * Route middleware that creates a request-scoped tracker. JAX sets the
 * uncompressed and actual prompt boundaries after it has assembled the system
 * prompt; response bookkeeping remains explicit so SSE and JSON both work.
 */
export function tokenTrackerMiddleware(req: Request, res: Response, next: NextFunction): void {
  res.locals.tokenTelemetryRequestStartedAt = performance.now();
  res.locals.tokenTelemetryRequestId = req.header("x-request-id") ?? randomUUID();
  next();
}

import { createHash, timingSafeEqual } from "node:crypto";

export type TelemetryReportSchedule = "daily" | "weekly" | "monthly";

export type TelemetryClientConfig = {
  clientId: string;
  tokenSha256: string;
  email?: string;
  schedule?: TelemetryReportSchedule;
  timezone: string;
};

type RawTelemetryClientConfig = {
  clientId?: unknown;
  token?: unknown;
  tokenSha256?: unknown;
  email?: unknown;
  schedule?: unknown;
  timezone?: unknown;
};

const TOKEN_HASH_PATTERN = /^[a-f0-9]{64}$/i;
const MIN_CAPABILITY_TOKEN_LENGTH = 24;

function hashCapabilityToken(token: string): string {
  return createHash("sha256").update(token, "utf8").digest("hex");
}

function isSchedule(value: unknown): value is TelemetryReportSchedule {
  return value === "daily" || value === "weekly" || value === "monthly";
}

function normalizeEntry(raw: RawTelemetryClientConfig): TelemetryClientConfig | null {
  const clientId = typeof raw.clientId === "string" ? raw.clientId.trim() : "";
  if (!clientId) return null;

  const plainToken = typeof raw.token === "string" ? raw.token.trim() : "";
  const configuredHash =
    typeof raw.tokenSha256 === "string" ? raw.tokenSha256.trim().toLowerCase() : "";
  const tokenSha256 = configuredHash && TOKEN_HASH_PATTERN.test(configuredHash)
    ? configuredHash
    : plainToken.length >= MIN_CAPABILITY_TOKEN_LENGTH
      ? hashCapabilityToken(plainToken)
      : "";
  if (!tokenSha256) return null;

  const email = typeof raw.email === "string" && raw.email.trim()
    ? raw.email.trim()
    : undefined;
  const schedule = isSchedule(raw.schedule) ? raw.schedule : undefined;
  const timezone = typeof raw.timezone === "string" && raw.timezone.trim()
    ? raw.timezone.trim()
    : "UTC";

  return { clientId, tokenSha256, email, schedule, timezone };
}

/**
 * Parse the capability-token mapping from environment configuration.
 *
 * Shape:
 * [{"clientId":"client-a","tokenSha256":"<sha256>","email":"ops@example.com",
 *   "schedule":"weekly","timezone":"America/Chicago"}]
 *
 * A `token` field is also accepted for secrets-managed plaintext tokens. The
 * returned structure contains only its hash.
 */
export function loadTelemetryClientConfigs(
  serialized = process.env.GKA_LIVE_TELEMETRY_CLIENTS,
): TelemetryClientConfig[] {
  if (!serialized?.trim()) return [];

  let parsed: unknown;
  try {
    parsed = JSON.parse(serialized);
  } catch {
    console.error("GKA live telemetry client configuration is invalid JSON");
    return [];
  }
  if (!Array.isArray(parsed)) {
    console.error("GKA live telemetry client configuration must be an array");
    return [];
  }

  const configs = parsed
    .map((entry) =>
      entry && typeof entry === "object"
        ? normalizeEntry(entry as RawTelemetryClientConfig)
        : null,
    )
    .filter((entry): entry is TelemetryClientConfig => Boolean(entry));

  if (configs.length !== parsed.length) {
    console.error("One or more GKA live telemetry client entries were rejected");
  }
  const hashCounts = new Map<string, number>();
  for (const config of configs) {
    hashCounts.set(config.tokenSha256, (hashCounts.get(config.tokenSha256) ?? 0) + 1);
  }
  const uniqueConfigs = configs.filter(
    (config) => hashCounts.get(config.tokenSha256) === 1,
  );
  if (uniqueConfigs.length !== configs.length) {
    console.error("Duplicate GKA live telemetry capability tokens were rejected");
  }
  return uniqueConfigs;
}

/**
 * Constant-time capability lookup. All configured hashes are compared before a
 * match is returned, preventing early-exit timing from identifying an entry.
 */
export function resolveTelemetryClient(
  presentedToken: string,
  configs = loadTelemetryClientConfigs(),
): TelemetryClientConfig | null {
  const token = presentedToken.trim();
  if (!token) return null;
  const presentedHash = Buffer.from(hashCapabilityToken(token), "hex");
  let matched: TelemetryClientConfig | null = null;

  for (const config of configs) {
    const configuredHash = Buffer.from(config.tokenSha256, "hex");
    if (
      configuredHash.length === presentedHash.length &&
      timingSafeEqual(configuredHash, presentedHash)
    ) {
      matched = config;
    }
  }
  return matched;
}

import cron from "node-cron";
import nodemailer, { type Transporter } from "nodemailer";
import {
  loadTelemetryClientConfigs,
  type TelemetryClientConfig,
  type TelemetryReportSchedule,
} from "./liveTelemetryConfig";
import {
  readTokenTelemetryLedger,
  type TokenTelemetryRecord,
} from "../middleware/tokenTracker";
import { logger } from "./logger";

type TelemetryReport = {
  clientId: string;
  schedule: TelemetryReportSchedule;
  periodStart: string;
  periodEnd: string;
  records: TokenTelemetryRecord[];
  totalTokensSuppressed: number;
  totalDollarsSaved: number;
  totalGkaGainShareDue: number;
  html: string;
  text: string;
  jsonl: string;
};

const scheduleExpressions: Record<TelemetryReportSchedule, string> = {
  daily: "0 8 * * *",
  weekly: "0 8 * * 1",
  monthly: "0 8 1 * *",
};

function roundMoney(value: number): number {
  return Number(value.toFixed(6));
}

function periodStart(schedule: TelemetryReportSchedule, now: Date): Date {
  const start = new Date(now);
  if (schedule === "daily") {
    start.setUTCDate(start.getUTCDate() - 1);
  } else if (schedule === "weekly") {
    start.setUTCDate(start.getUTCDate() - 7);
  } else {
    start.setUTCMonth(start.getUTCMonth() - 1);
  }
  return start;
}

function escapeHtml(value: string): string {
  return value
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

export function buildTelemetryReport(
  clientId: string,
  schedule: TelemetryReportSchedule,
  records: TokenTelemetryRecord[],
  now = new Date(),
): TelemetryReport {
  const start = periodStart(schedule, now);
  const verified = records.filter((record) => {
    if (record.client_id !== clientId || record.status !== "completed") return false;
    const createdAt = new Date(record.created_at);
    return Number.isFinite(createdAt.getTime()) && createdAt >= start && createdAt <= now;
  });
  const totals = verified.reduce(
    (result, record) => {
      result.totalTokensSuppressed += record.tokens_suppressed;
      result.totalDollarsSaved += record.dollar_savings;
      result.totalGkaGainShareDue += record.gka_gain_share_due;
      return result;
    },
    { totalTokensSuppressed: 0, totalDollarsSaved: 0, totalGkaGainShareDue: 0 },
  );
  const dollarsSaved = roundMoney(totals.totalDollarsSaved);
  const gainShare = roundMoney(totals.totalGkaGainShareDue);
  const safeClientId = escapeHtml(clientId);
  const range = `${start.toISOString()} — ${now.toISOString()}`;
  const html = `<!doctype html>
<html><body style="margin:0;background:#f4f7f9;font-family:Arial,sans-serif;color:#17212b">
<div style="max-width:680px;margin:0 auto;padding:32px">
  <h1 style="margin:0 0 8px">GravelKing telemetry report</h1>
  <p style="margin:0 0 24px;color:#52606d">${safeClientId} · ${schedule} · ${range}</p>
  <div style="background:#fff;border:1px solid #d8e0e6;border-radius:10px;padding:24px">
    <p style="margin:0 0 10px"><strong>Total Dollars Saved:</strong> $${dollarsSaved.toFixed(6)}</p>
    <p style="margin:0 0 10px"><strong>Tokens Suppressed:</strong> ${totals.totalTokensSuppressed.toLocaleString("en-US")}</p>
    <p style="margin:0"><strong>Verified Records:</strong> ${verified.length}</p>
  </div>
  <p style="color:#52606d">The attached JSONL file contains only telemetry mapped to this client.</p>
</div></body></html>`;
  const text = [
    "GravelKing telemetry report",
    `Client: ${clientId}`,
    `Period: ${range}`,
    `Total Dollars Saved: $${dollarsSaved.toFixed(6)}`,
    `Tokens Suppressed: ${totals.totalTokensSuppressed}`,
    `Verified Records: ${verified.length}`,
  ].join("\n");

  return {
    clientId,
    schedule,
    periodStart: start.toISOString(),
    periodEnd: now.toISOString(),
    records: verified,
    totalTokensSuppressed: totals.totalTokensSuppressed,
    totalDollarsSaved: dollarsSaved,
    totalGkaGainShareDue: gainShare,
    html,
    text,
    jsonl: verified.map((record) => JSON.stringify(record)).join("\n") + (verified.length ? "\n" : ""),
  };
}

function smtpTransport(): { transport: Transporter; from: string } | null {
  const host = process.env.GKA_SMTP_HOST?.trim();
  const user = process.env.GKA_SMTP_USER?.trim();
  const password = process.env.GKA_SMTP_PASSWORD;
  const from = process.env.GKA_SMTP_FROM?.trim();
  const port = Number(process.env.GKA_SMTP_PORT ?? 587);
  if (!host || !user || !password || !from || !Number.isInteger(port) || port <= 0) {
    return null;
  }
  return {
    transport: nodemailer.createTransport({
      host,
      port,
      secure: process.env.GKA_SMTP_SECURE === "true" || port === 465,
      auth: { user, pass: password },
    }),
    from,
  };
}

export async function sendTelemetryReport(
  client: TelemetryClientConfig,
  mailer = smtpTransport(),
  now = new Date(),
): Promise<boolean> {
  if (!client.email || !client.schedule || !mailer) return false;
  const records = await readTokenTelemetryLedger(client.clientId);
  const report = buildTelemetryReport(client.clientId, client.schedule, records, now);
  const date = now.toISOString().slice(0, 10);
  await mailer.transport.sendMail({
    from: mailer.from,
    to: client.email,
    subject: `GravelKing ${client.schedule} telemetry report — ${date}`,
    text: report.text,
    html: report.html,
    attachments: [{
      filename: `gka-telemetry-${client.clientId}-${date}.jsonl`,
      content: Buffer.from(report.jsonl, "utf8"),
      contentType: "application/x-ndjson",
    }],
  });
  return true;
}

export function scheduleTelemetryReports(): void {
  const mailer = smtpTransport();
  const configuredReportClients = loadTelemetryClientConfigs().filter(
    (client) => client.email && client.schedule,
  );
  const uniqueReportClients = new Map<string, TelemetryClientConfig>();
  for (const client of configuredReportClients) {
    uniqueReportClients.set(
      `${client.clientId}:${client.email}:${client.schedule}`,
      client,
    );
  }
  const reportClients = [...uniqueReportClients.values()];
  if (!mailer || reportClients.length === 0) {
    logger.info("GKA telemetry email scheduler disabled: SMTP or report clients not configured");
    return;
  }

  const activeClients = new Set<string>();
  for (const client of reportClients) {
    cron.schedule(
      scheduleExpressions[client.schedule!],
      async () => {
        const lockKey = `${client.clientId}:${client.schedule}`;
        if (activeClients.has(lockKey)) return;
        activeClients.add(lockKey);
        try {
          await sendTelemetryReport(client, mailer);
          logger.info(
            { clientId: client.clientId, schedule: client.schedule },
            "GKA telemetry email report sent",
          );
        } catch (error) {
          logger.error(
            { error, clientId: client.clientId, schedule: client.schedule },
            "GKA telemetry email report failed",
          );
        } finally {
          activeClients.delete(lockKey);
        }
      },
      { timezone: client.timezone },
    );
  }
  logger.info({ clientCount: reportClients.length }, "GKA telemetry email scheduler registered");
}

import { createRequire } from "node:module";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { build as esbuild } from "esbuild";
import esbuildPluginPino from "esbuild-plugin-pino";
import { rm } from "node:fs/promises";

// Plugins (e.g. 'esbuild-plugin-pino') may use `require` to resolve dependencies
globalThis.require = createRequire(import.meta.url);

const artifactDir = path.dirname(fileURLToPath(import.meta.url));

async function buildAll() {
  const distDir = path.resolve(artifactDir, "dist");
  await rm(distDir, { recursive: true, force: true });

  await esbuild({
    entryPoints: [path.resolve(artifactDir, "src/index.ts")],
    platform: "node",
    bundle: true,
    format: "esm",
    outdir: distDir,
    outExtension: { ".js": ".mjs" },
    logLevel: "info",
    // Some packages may not be bundleable, so we externalize them, we can add more here as needed.
    // Some of the packages below may not be imported or installed, but we're adding them in case they are in the future.
    // Examples of unbundleable packages:
    // - uses native modules and loads them dynamically (e.g. sharp)
    // - use path traversal to read files (e.g. @google-cloud/secret-manager loads sibling .proto files)
    external: [
      // Externalize stripe and stripe-replit-sync so they run from node_modules at
      // runtime.  stripe-replit-sync uses __dirname to locate its SQL migration
      // files; if esbuild bundles it the __dirname points to our dist/ output
      // folder and the migrations directory is never found, so runMigrations()
      // silently skips all table creation.
      "stripe",
      "stripe-replit-sync",
      "*.node",
      "sharp",
      "better-sqlite3",
      "sqlite3",
      "canvas",
      "bcrypt",
      "argon2",
      "fsevents",
      "re2",
      "farmhash",
      "xxhash-addon",
      "bufferutil",
      "utf-8-validate",
      "ssh2",
      "cpu-features",
      "dtrace-provider",
      "isolated-vm",
      "lightningcss",
      "pg-native",
      "oracledb",
      "mongodb-client-encryption",
      "nodemailer",
      "handlebars",
      "knex",
      "typeorm",
      "protobufjs",
      "onnxruntime-node",
      "@tensorflow/*",
      "@prisma/client",
      "@mikro-orm/*",
      "@grpc/*",
      "@swc/*",
      "@aws-sdk/*",
      "@azure/*",
      "@opentelemetry/*",
      "@google-cloud/*",
      "@google/*",
      "googleapis",
      "firebase-admin",
      "@parcel/watcher",
      "@sentry/profiling-node",
      "@tree-sitter/*",
      "aws-sdk",
      "classic-level",
      "dd-trace",
      "ffi-napi",
      "grpc",
      "hiredis",
      "kerberos",
      "leveldown",
      "miniflare",
      "mysql2",
      "newrelic",
      "odbc",
      "piscina",
      "realm",
      "ref-napi",
      "rocksdb",
      "sass-embedded",
      "sequelize",
      "serialport",
      "snappy",
      "tinypool",
      "usb",
      "workerd",
      "wrangler",
      "zeromq",
      "zeromq-prebuilt",
      "playwright",
      "puppeteer",
      "puppeteer-core",
      "electron",
    ],
    sourcemap: "linked",
    plugins: [
      // pino relies on workers to handle logging, instead of externalizing it we use a plugin to handle it
      esbuildPluginPino({ transports: ["pino-pretty"] })
    ],
    // Make sure packages that are cjs only (e.g. express) but are bundled continue to work in our esm output file
    banner: {
      js: `import { createRequire as __bannerCrReq } from 'node:module';
import __bannerPath from 'node:path';
import __bannerUrl from 'node:url';

globalThis.require = __bannerCrReq(import.meta.url);
globalThis.__filename = __bannerUrl.fileURLToPath(import.meta.url);
globalThis.__dirname = __bannerPath.dirname(globalThis.__filename);
    `,
    },
  });
}

buildAll().catch((err) => {
  console.error(err);
  process.exit(1);
});

